def _v(*c):
    """Column vector in LaTeX (no dollar signs)."""
    return r"\begin{pmatrix} " + r" \\ ".join(str(x) for x in c) + r" \end{pmatrix}"


M_VEC = "3D Vector Geometry"
M_HYP = "Hyperbolic Functions & Polar Coordinates"
M_CON = "Conic Sections & Rational Functions"

T_VP = "Vector product and the scalar triple product"
T_LP = "Lines and planes"
T_SD = "Shortest distances and angles"
T_HF = "Hyperbolic functions and identities"
T_IH = "Inverse hyperbolic functions"
T_PC = "Polar curves"
T_PA = "Area in polar coordinates"
T_CS = "Parabola, ellipse and hyperbola"
T_TN = "Tangents and normals to conics"
T_RF = "Rational functions and oblique asymptotes"

# ---------------------------------------------------------------- 1. The vector product
LESSONS.append(lesson(
    module=M_VEC, topic=T_VP,
    title="The vector product and areas",
    slug="fml2-vector-product-and-areas",
    minutes=22,
    summary="Define and calculate the vector product a x b, use it to find a vector perpendicular to two others, the angle between vectors, and the area of a parallelogram or triangle in space.",
    objectives=[
        "Calculate a x b from components using the determinant layout",
        "Use a x b to find a vector or unit vector perpendicular to two given vectors",
        "Use |a x b| = |a||b| sin(theta) to find angles and test whether vectors are parallel",
        "Find the area of a parallelogram or a triangle in three dimensions",
    ],
    key_concepts=["Vector product", "Right-hand rule", "Parallel vectors", "Area of a parallelogram", "Area of a triangle"],
    blocks=[
        H("Introduction"),
        T(r"A mechanic in Douala tightens a wheel nut with a spanner. The turning effect (the **moment**) depends on the force, on how long the spanner is and on the angle between them, and it acts along an axis at right angles to both the spanner and the force. A quantity like this needs an operation that takes two vectors and returns a third vector. That operation is the **vector product**."),
        T(r"In Core Pure you used the scalar product, which gives a number. The vector product gives a vector, and it exists only in three dimensions."),
        H("Definition"),
        D(r"For vectors $\mathbf{a}$ and $\mathbf{b}$ with angle $\theta$ between them ($0^\circ \le \theta \le 180^\circ$):", title="Vector (cross) product",
          formula=r"\mathbf{a}\times\mathbf{b} = |\mathbf{a}|\,|\mathbf{b}|\sin\theta\;\hat{\mathbf{n}}",
          note=r"$\hat{\mathbf{n}}$ is the unit vector perpendicular to both $\mathbf{a}$ and $\mathbf{b}$, in the direction given by the right-hand rule: curl the fingers of your right hand from $\mathbf{a}$ towards $\mathbf{b}$ and the thumb points along $\hat{\mathbf{n}}$."),
        IMG("al-fml2-cross-product.svg", alt="Two vectors a and b drawn from one point with a shaded parallelogram between them and the vector a cross b standing at right angles to the parallelogram.",
            caption="Figure 1. The vector a x b is perpendicular to the parallelogram; its length is the area of the parallelogram."),
        H("Calculating from components"),
        D(r"If $\mathbf{a} = (a_1, a_2, a_3)$ and $\mathbf{b} = (b_1, b_2, b_3)$:", title="Component form",
          formula=r"\mathbf{a}\times\mathbf{b} = \begin{vmatrix} \mathbf{i} & \mathbf{j} & \mathbf{k} \\ a_1 & a_2 & a_3 \\ b_1 & b_2 & b_3 \end{vmatrix} = \begin{pmatrix} a_2b_3 - a_3b_2 \\ a_3b_1 - a_1b_3 \\ a_1b_2 - a_2b_1 \end{pmatrix}",
          note=r"Expand along the top row. The $\mathbf{j}$ term carries a minus sign, which is why the middle component is written $a_3b_1 - a_1b_3$."),
        EX("Worked example 1: a vector product and its checks", intro=r"Find $\mathbf{a}\times\mathbf{b}$ for $\mathbf{a} = (3, 1, -2)$ and $\mathbf{b} = (1, 4, 5)$, and show that the result is perpendicular to both.", steps=[
            S("First component: cover column 1", math=r"a_2b_3 - a_3b_2 = (1)(5) - (-2)(4) = 13"),
            S("Second component", math=r"a_3b_1 - a_1b_3 = (-2)(1) - (3)(5) = -17"),
            S("Third component", math=r"a_1b_2 - a_2b_1 = (3)(4) - (1)(1) = 11", text=r"So $\mathbf{a}\times\mathbf{b} = (13, -17, 11)$."),
            S("Check with scalar products", math=r"(13,-17,11)\cdot(3,1,-2) = 39 - 17 - 22 = 0, \qquad (13,-17,11)\cdot(1,4,5) = 13 - 68 + 55 = 0", text=r"Both are zero, so the result is perpendicular to $\mathbf{a}$ and to $\mathbf{b}$."),
        ]),
        KEY("Rules of the vector product", "Learn these; they save marks and time.", cards=[
            [r"$\mathbf{b}\times\mathbf{a} = -(\mathbf{a}\times\mathbf{b})$", "The order matters: swapping the vectors reverses the direction."],
            [r"$\mathbf{a}\times\mathbf{a} = \mathbf{0}$", r"Because $\sin 0^\circ = 0$. Note the result is the zero **vector**, not the number 0."],
            [r"$\mathbf{a}\times(\mathbf{b}+\mathbf{c}) = \mathbf{a}\times\mathbf{b} + \mathbf{a}\times\mathbf{c}$", "It expands over addition, keeping the order."],
            [r"$\mathbf{a}\times\mathbf{b} = \mathbf{0}$", "The vectors are parallel (or one is zero)."],
        ]),
        T(r"The vector product is **not associative**: in general $(\mathbf{a}\times\mathbf{b})\times\mathbf{c} \ne \mathbf{a}\times(\mathbf{b}\times\mathbf{c})$, so never remove brackets in a repeated product."),
        H("Perpendicular vectors and angles"),
        EX("Worked example 2: a unit normal", intro=r"Find a unit vector perpendicular to both $\mathbf{p} = (1, -2, 3)$ and $\mathbf{q} = (2, 1, -1)$.", steps=[
            S("The vector product is perpendicular to both", math=r"\mathbf{p}\times\mathbf{q} = \begin{pmatrix} (-2)(-1) - (3)(1) \\ (3)(2) - (1)(-1) \\ (1)(1) - (-2)(2) \end{pmatrix} = \begin{pmatrix} -1 \\ 7 \\ 5 \end{pmatrix}"),
            S("Find its magnitude", math=r"\sqrt{1 + 49 + 25} = \sqrt{75} = 5\sqrt{3}"),
            S("Divide by the magnitude", math=r"\hat{\mathbf{n}} = \frac{1}{5\sqrt{3}}(-1, 7, 5)", text="The opposite vector is also a unit vector perpendicular to both."),
        ]),
        EX("Worked example 3: an angle from the vector product", intro=r"Find the angle between $\mathbf{a} = (1, 2, 3)$ and $\mathbf{b} = (2, -1, 1)$ using $|\mathbf{a}\times\mathbf{b}| = |\mathbf{a}||\mathbf{b}|\sin\theta$.", steps=[
            S("Vector product", math=r"\mathbf{a}\times\mathbf{b} = (2 + 3,\ 6 - 1,\ -1 - 4) = (5, 5, -5)", text=r"Its magnitude is $5\sqrt{3}$."),
            S("Magnitudes of the vectors", math=r"|\mathbf{a}||\mathbf{b}| = \sqrt{14}\sqrt{6} = \sqrt{84}"),
            S("Solve for sine", math=r"\sin\theta = \frac{5\sqrt{3}}{\sqrt{84}} = 0.9449"),
            S("The scalar product tells acute from obtuse", math=r"\mathbf{a}\cdot\mathbf{b} = 2 - 2 + 3 = 3 > 0", text=r"The angle is acute, so $\theta = 70.9^\circ$."),
        ], check=r"\cos\theta = \frac{3}{\sqrt{84}} = 0.3273 \Rightarrow \theta = 70.9^\circ"),
        TIP(r"A sine value gives two angles, $\theta$ and $180^\circ - \theta$. Use the sign of $\mathbf{a}\cdot\mathbf{b}$ to choose, or simply use the scalar product for the angle and keep the vector product for areas and perpendiculars."),
        H("Areas"),
        D(r"The parallelogram with adjacent sides $\mathbf{a}$ and $\mathbf{b}$ has area $|\mathbf{a}||\mathbf{b}|\sin\theta$, which is the magnitude of the vector product. A triangle is half of it.", title="Area formulae",
          formula=r"\text{Parallelogram} = |\mathbf{a}\times\mathbf{b}|, \qquad \text{Triangle } ABC = \tfrac{1}{2}\left|\overrightarrow{AB}\times\overrightarrow{AC}\right|"),
        EX("Worked example 4: area of a triangular plot", intro=r"A triangular plot has corners $A(1, 0, 2)$, $B(3, 1, 1)$ and $C(2, 3, 4)$ (metres, on a sloping site). Find its area.", steps=[
            S("Two sides from $A$", math=r"\overrightarrow{AB} = (2, 1, -1), \qquad \overrightarrow{AC} = (1, 3, 2)"),
            S("Vector product", math=r"\overrightarrow{AB}\times\overrightarrow{AC} = (2 + 3,\ -1 - 4,\ 6 - 1) = (5, -5, 5)"),
            S("Half the magnitude", math=r"\text{Area} = \tfrac{1}{2}\sqrt{25 + 25 + 25} = \tfrac{5\sqrt{3}}{2} \approx 4.33 \text{ m}^2"),
        ]),
        MISTAKE("Swapping the order", r"$\mathbf{a}\times\mathbf{b}$ and $\mathbf{b}\times\mathbf{a}$ point in opposite directions. In a question that fixes the direction (for example 'pointing upwards'), the order of the product decides the sign."),
        MISTAKE("Dropping the minus sign on the middle component", r"The middle component is $a_3b_1 - a_1b_3$, not $a_1b_3 - a_3b_1$. Always test the answer: its scalar product with each original vector must be $0$."),
        MISTAKE("Using the vector product in two dimensions or as a number", r"$\mathbf{a}\times\mathbf{b}$ is a vector. Writing $\mathbf{a}\times\mathbf{b} = 8$ is wrong; the number $8$ may be its magnitude, written $|\mathbf{a}\times\mathbf{b}| = 8$."),
        QUIZ(r"$|\mathbf{a}| = 3$, $|\mathbf{b}| = 4$ and the angle between them is $30^\circ$. What is $|\mathbf{a}\times\mathbf{b}|$?",
             ["$12$", "$6$", r"$6\sqrt{3}$", r"$12\sqrt{3}$"], 1,
             r"$|\mathbf{a}||\mathbf{b}|\sin 30^\circ = 12 \times \tfrac{1}{2} = 6$.", hint="Which trigonometric function goes with the vector product?",
             feedback=[r"This forgets the sine: $12$ is $|\mathbf{a}||\mathbf{b}|$.", "", r"This uses $\cos 30^\circ = \frac{\sqrt{3}}{2}$ (the scalar product's function) instead of $\sin 30^\circ$.", r"$12\sqrt{3}$ is not even a sensible size: $\sin\theta \le 1$ so the answer cannot exceed $12$."]),
        QUIZ(r"Which statement about $\mathbf{u}\times\mathbf{v} = \mathbf{0}$ (with $\mathbf{u}, \mathbf{v}$ non-zero) is true?",
             [r"$\mathbf{u}$ and $\mathbf{v}$ are perpendicular", r"$\mathbf{u}$ and $\mathbf{v}$ are parallel", r"$\mathbf{u} = \mathbf{v}$ only", r"$\mathbf{u}\cdot\mathbf{v} = 0$"], 1,
             r"$\sin\theta = 0$ means $\theta = 0^\circ$ or $180^\circ$: the vectors are parallel.", hint=r"For which angles is $\sin\theta = 0$?",
             feedback=["Perpendicular vectors have a scalar product of zero; their vector product is as large as possible.", "", "Equal vectors are parallel, but so is any scalar multiple, so 'only' is wrong.", "That says they are perpendicular, the opposite case."]),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for a vector product, a unit normal or an area. In Paper 2 the vector product is used to build the normal of a plane (next lessons), so accuracy in the components matters.", title="Exam link"),
        H("Practice questions"),
        PQ(r"Find $\mathbf{a}\times\mathbf{b}$ where $\mathbf{a} = (2, -1, 4)$ and $\mathbf{b} = (1, 3, -2)$, and check that it is perpendicular to $\mathbf{a}$.",
           r"$\mathbf{a}\times\mathbf{b} = ((-1)(-2) - (4)(3),\ (4)(1) - (2)(-2),\ (2)(3) - (-1)(1)) = (2 - 12,\ 4 + 4,\ 6 + 1) = (-10, 8, 7)$. Check: $(-10)(2) + (8)(-1) + (7)(4) = -20 - 8 + 28 = 0$."),
        PQ(r"Find a unit vector perpendicular to both $(1, 1, 0)$ and $(0, 1, 1)$.",
           r"The cross product is $(1\cdot 1 - 0\cdot 1,\ 0\cdot 0 - 1\cdot 1,\ 1\cdot 1 - 1\cdot 0) = (1, -1, 1)$. Its magnitude is $\sqrt{3}$. The unit vector is $\frac{1}{\sqrt{3}}(1, -1, 1)$ (or its negative)."),
        PQ(r"The parallelogram $ABCD$ has $A(1, 0, 0)$, $B(3, 1, 2)$ and $D(0, 2, 1)$. Find its area.",
           r"$\overrightarrow{AB} = (2, 1, 2)$ and $\overrightarrow{AD} = (-1, 2, 1)$. $\overrightarrow{AB}\times\overrightarrow{AD} = (1 - 4,\ -2 - 2,\ 4 + 1) = (-3, -4, 5)$. Area $= \sqrt{9 + 16 + 25} = \sqrt{50} = 5\sqrt{2} \approx 7.07$ square units."),
        PQ(r"Find the angle between $\mathbf{a} = (1, 2, 3)$ and $\mathbf{b} = (2, -1, 1)$ using the scalar product, and confirm that $|\mathbf{a}\times\mathbf{b}|^2 + (\mathbf{a}\cdot\mathbf{b})^2 = |\mathbf{a}|^2|\mathbf{b}|^2$.",
           r"$\cos\theta = \frac{3}{\sqrt{14}\sqrt{6}} = 0.3273$, so $\theta = 70.9^\circ$. Check: $|\mathbf{a}\times\mathbf{b}|^2 = 75$ and $(\mathbf{a}\cdot\mathbf{b})^2 = 9$, so the sum is $84 = 14 \times 6$. This is $\sin^2\theta + \cos^2\theta = 1$ multiplied by $|\mathbf{a}|^2|\mathbf{b}|^2$."),
        H("Summary"),
        SUM(r"$\mathbf{a}\times\mathbf{b} = |\mathbf{a}||\mathbf{b}|\sin\theta\,\hat{\mathbf{n}}$, perpendicular to both vectors, direction by the right-hand rule.",
            r"Components: $(a_2b_3 - a_3b_2,\ a_3b_1 - a_1b_3,\ a_1b_2 - a_2b_1)$. Check by taking scalar products with $\mathbf{a}$ and $\mathbf{b}$.",
            r"$\mathbf{b}\times\mathbf{a} = -\mathbf{a}\times\mathbf{b}$, $\mathbf{a}\times\mathbf{a} = \mathbf{0}$, and $\mathbf{a}\times\mathbf{b} = \mathbf{0}$ means parallel.",
            r"Parallelogram area $= |\mathbf{a}\times\mathbf{b}|$; triangle area $= \frac{1}{2}|\overrightarrow{AB}\times\overrightarrow{AC}|$."),
    ],
))

# ---------------------------------------------------------------- 2. The scalar triple product
LESSONS.append(lesson(
    module=M_VEC, topic=T_VP,
    title="The scalar triple product: volumes and coplanar vectors",
    slug="fml2-scalar-triple-product",
    minutes=22,
    summary="Use a.(b x c) as a 3 by 3 determinant to find the volume of a parallelepiped or tetrahedron and to test whether vectors or points lie in one plane.",
    objectives=[
        "Calculate the scalar triple product a.(b x c) as a determinant",
        "Find the volume of a parallelepiped and of a tetrahedron",
        "Use the triple product to test for coplanar vectors and points, and to find an unknown",
        "Find the height of a tetrahedron above a face",
    ],
    key_concepts=["Scalar triple product", "Parallelepiped", "Tetrahedron", "Coplanar", "Determinant"],
    blocks=[
        H("Introduction"),
        T(r"A builder in Bamenda must order concrete for a block whose edges are not at right angles, such as a sloping foundation. A surveyor wants to know whether four survey pegs lie on one flat plane. Both questions are answered by one number built from three vectors: the **scalar triple product**."),
        H("Definition"),
        D(r"For three vectors $\mathbf{a}$, $\mathbf{b}$, $\mathbf{c}$, the scalar triple product is $\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})$. It is a **number**, and it equals the determinant of the three vectors written as rows.", title="Scalar triple product",
          formula=r"\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c}) = \begin{vmatrix} a_1 & a_2 & a_3 \\ b_1 & b_2 & b_3 \\ c_1 & c_2 & c_3 \end{vmatrix}",
          note=r"Work out $\mathbf{b}\times\mathbf{c}$ first, then take the scalar product with $\mathbf{a}$, or expand the determinant along the first row."),
        KEY("Properties", "These follow from the determinant.", cards=[
            [r"$\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c}) = \mathbf{b}\cdot(\mathbf{c}\times\mathbf{a}) = \mathbf{c}\cdot(\mathbf{a}\times\mathbf{b})$", "Cyclic order keeps the value."],
            [r"Swap two vectors", "The sign changes, for example $\\mathbf{a}\\cdot(\\mathbf{c}\\times\\mathbf{b}) = -\\mathbf{a}\\cdot(\\mathbf{b}\\times\\mathbf{c})$."],
            [r"Two vectors equal or parallel", "The triple product is $0$."],
            [r"Triple product $= 0$", "The three vectors are coplanar (lie in one plane through a common point)."],
        ]),
        H("Volume"),
        D(r"The parallelepiped (a slanted box) with edges $\mathbf{a}$, $\mathbf{b}$, $\mathbf{c}$ from one corner has base area $|\mathbf{b}\times\mathbf{c}|$ and height $|\mathbf{a}|\cos\varphi$, where $\varphi$ is the angle between $\mathbf{a}$ and the normal $\mathbf{b}\times\mathbf{c}$. So:", title="Volumes",
          formula=r"V_{\text{parallelepiped}} = \left|\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})\right|, \qquad V_{\text{tetrahedron}} = \tfrac{1}{6}\left|\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})\right|",
          note=r"A tetrahedron with the same three edges fills one sixth of the parallelepiped: a pyramid is $\frac{1}{3}$ of a prism, and the triangular base is $\frac{1}{2}$ of the parallelogram."),
        EX("Worked example 1: volume of a parallelepiped", intro=r"Find the volume of the parallelepiped with edges $\mathbf{a} = (2, 0, 1)$, $\mathbf{b} = (1, 3, 0)$, $\mathbf{c} = (0, 1, 4)$.", steps=[
            S("Find $\\mathbf{b}\\times\\mathbf{c}$", math=r"\mathbf{b}\times\mathbf{c} = (3\cdot 4 - 0\cdot 1,\ 0\cdot 0 - 1\cdot 4,\ 1\cdot 1 - 3\cdot 0) = (12, -4, 1)"),
            S("Scalar product with $\\mathbf{a}$", math=r"\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c}) = 24 + 0 + 1 = 25"),
            S("Volume is the absolute value", math=r"V = 25 \text{ cubic units}"),
        ], check=r"\begin{vmatrix} 2 & 0 & 1 \\ 1 & 3 & 0 \\ 0 & 1 & 4 \end{vmatrix} = 2(12) - 0 + 1(1) = 25"),
        EX("Worked example 2: a tetrahedron and its height", intro=r"The tetrahedron $ABCD$ has $A(1, 1, 1)$, $B(3, 2, 1)$, $C(2, 4, 2)$, $D(1, 2, 5)$. Find its volume and the perpendicular height of $D$ above the face $ABC$.", steps=[
            S("Edges from $A$", math=r"\overrightarrow{AB} = (2, 1, 0), \quad \overrightarrow{AC} = (1, 3, 1), \quad \overrightarrow{AD} = (0, 1, 4)"),
            S("Triple product", math=r"\overrightarrow{AC}\times\overrightarrow{AD} = (11, -4, 1), \qquad \overrightarrow{AB}\cdot(11, -4, 1) = 22 - 4 + 0 = 18"),
            S("Volume of the tetrahedron", math=r"V = \tfrac{1}{6}(18) = 3"),
            S("Area of the base $ABC$", math=r"\overrightarrow{AB}\times\overrightarrow{AC} = (1, -2, 5), \qquad \text{Area} = \tfrac{1}{2}\sqrt{30} = 2.739"),
            S("Use $V = \\frac{1}{3}\\times\\text{base}\\times h$", math=r"h = \frac{3V}{\text{Area}} = \frac{9}{\frac{1}{2}\sqrt{30}} = \frac{18}{\sqrt{30}} \approx 3.29", text="The height is about 3.29 units."),
        ], check=r"\text{Distance of } D \text{ from the plane with normal } (1,-2,5): \ \frac{|(0,1,4)\cdot(1,-2,5)|}{\sqrt{30}} = \frac{18}{\sqrt{30}}"),
        H("Coplanar vectors and points"),
        T(r"If $\mathbf{a}$, $\mathbf{b}$, $\mathbf{c}$ lie in one plane the 'box' they make is flat and has zero volume. So three vectors are coplanar exactly when $\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c}) = 0$. Four points $A, B, C, D$ are coplanar when $\overrightarrow{AB}$, $\overrightarrow{AC}$, $\overrightarrow{AD}$ are coplanar."),
        EX("Worked example 3: finding an unknown", intro=r"Find $k$ so that $(1, 2, -1)$, $(3, k, 2)$ and $(2, 1, 1)$ are coplanar.", steps=[
            S("Set the determinant to zero", math=r"\begin{vmatrix} 1 & 2 & -1 \\ 3 & k & 2 \\ 2 & 1 & 1 \end{vmatrix} = 0"),
            S("Expand along the first row", math=r"1(k - 2) - 2(3 - 4) + (-1)(3 - 2k) = 0"),
            S("Simplify", math=r"k - 2 + 2 - 3 + 2k = 3k - 3 = 0", text=r"So $k = 1$."),
        ], check=r"k = 1:\ 1(1 - 2) - 2(3 - 4) + (-1)(3 - 2) = -1 + 2 - 1 = 0 \ \checkmark"),
        MISTAKE("Forgetting the absolute value", r"The triple product can be negative (it depends on the order of the vectors), but a volume cannot. Write $V = |\ldots|$."),
        MISTAKE("Forgetting the factor one sixth", r"A parallelepiped has volume $|\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})|$, a tetrahedron on the same edges has one sixth of it, and a triangular pyramid is not one half."),
        MISTAKE("Using position vectors for four points", r"To test four points for coplanarity use three **edge** vectors from one of the points, such as $\overrightarrow{AB}$, $\overrightarrow{AC}$, $\overrightarrow{AD}$, not the position vectors of the points."),
        QUIZ(r"$\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c}) = 12$. What is $\mathbf{b}\cdot(\mathbf{a}\times\mathbf{c})$?",
             ["$12$", "$-12$", "$0$", "$144$"], 1,
             r"$\mathbf{b}\cdot(\mathbf{a}\times\mathbf{c})$ swaps $\mathbf{a}$ and $\mathbf{b}$ compared with the cyclic order $\mathbf{b}\cdot(\mathbf{c}\times\mathbf{a})$, so the sign changes.", hint="Is this a cyclic rearrangement or a swap?",
             feedback=["Only cyclic rearrangements keep the sign. Here two vectors have been swapped.", "", "The product is zero only when the vectors are coplanar, and here it is $\\pm 12$.", "Nothing here squares the value."]),
        QUIZ(r"The tetrahedron with edges $\mathbf{a}$, $\mathbf{b}$, $\mathbf{c}$ has volume 5. What is $\left|\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})\right|$?",
             ["$5$", "$15$", "$30$", r"$\frac{5}{6}$"], 2,
             r"$V = \frac{1}{6}|\ldots|$, so $|\ldots| = 6 \times 5 = 30$.", hint="Tetrahedron volume is one sixth of the triple product.",
             feedback=["$5$ is the volume you were given, not the triple product: the factor $6$ has been ignored.", "That treats a tetrahedron as one third of the box.", "", "This divides by 6 instead of multiplying."]),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for a triple product, a volume or the value of $k$ making vectors coplanar. In Paper 2, volume and height of a tetrahedron appear in structured vector questions.", title="Exam link"),
        H("Practice questions"),
        PQ(r"Find $\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})$ for $\mathbf{a} = (1, 0, 2)$, $\mathbf{b} = (3, 1, -1)$, $\mathbf{c} = (2, 2, 1)$, and state the volume of the parallelepiped.",
           r"$\mathbf{b}\times\mathbf{c} = (1\cdot 1 - (-1)\cdot 2,\ (-1)\cdot 2 - 3\cdot 1,\ 3\cdot 2 - 1\cdot 2) = (3, -5, 4)$. Then $\mathbf{a}\cdot(3, -5, 4) = 3 + 0 + 8 = 11$. The volume is $11$ cubic units."),
        PQ(r"The tetrahedron $OABC$ has $\overrightarrow{OA} = (2, 1, 0)$, $\overrightarrow{OB} = (0, 3, 1)$, $\overrightarrow{OC} = (1, 0, 4)$. Find its volume.",
           r"$\overrightarrow{OB}\times\overrightarrow{OC} = (12, 1, -3)$, and $\overrightarrow{OA}\cdot(12, 1, -3) = 24 + 1 + 0 = 25$. $V = \frac{25}{6} \approx 4.17$ cubic units."),
        PQ(r"Show that the points $A(1, 2, 3)$, $B(2, 4, 5)$, $C(0, 1, 4)$, $D(1, 3, 6)$ are coplanar.",
           r"$\overrightarrow{AB} = (1, 2, 2)$, $\overrightarrow{AC} = (-1, -1, 1)$, $\overrightarrow{AD} = (0, 1, 3)$. $\overrightarrow{AC}\times\overrightarrow{AD} = (-4, 3, -1)$ and $\overrightarrow{AB}\cdot(-4, 3, -1) = -4 + 6 - 2 = 0$. The triple product is zero, so the points are coplanar. (Indeed $\overrightarrow{AD} = \overrightarrow{AB} + \overrightarrow{AC}$.)"),
        PQ(r"Find $k$ such that $(2, k, 1)$, $(1, 1, 2)$ and $(0, 3, 1)$ are coplanar.",
           r"$\begin{vmatrix} 2 & k & 1 \\ 1 & 1 & 2 \\ 0 & 3 & 1 \end{vmatrix} = 2(1 - 6) - k(1 - 0) + 1(3 - 0) = -10 - k + 3 = -7 - k$. This is $0$ when $k = -7$."),
        H("Summary"),
        SUM(r"$\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})$ is the $3\times 3$ determinant with the vectors as rows; it is a number.",
            r"Cyclic rearrangements keep the value; swapping two vectors changes the sign.",
            r"Parallelepiped volume $= |\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})|$; tetrahedron volume is $\frac{1}{6}$ of that.",
            r"Vectors are coplanar exactly when the triple product is $0$; for four points use three edges from one point.",
            r"Height of a tetrahedron above a face: $h = 3V \div \text{(area of the face)}$."),
    ],
))

